  const printSheet = async () => { await buildPrintSheet(); };
  const handleSignatureFile=(id:string,file?:File)=>{if(!file)return;if(!file.type.startsWith('image/')){setNotice('Choose a signature image.');return;}const customer=customers.find(c=>c.id===id);const baseUrl=customer?.signatureMerged&&customer.signatureBaseUrl?customer.signatureBaseUrl:customer?.workingUrl;updateCustomer(id,{signatureUrl:URL.createObjectURL(file),includeSignature:false,signatureMerged:false,workingUrl:baseUrl||customer?.workingUrl||'',signatureBaseUrl:undefined});setNotice('Signature uploaded; remove its background, place it on the photo, resize and merge.');};
